from pathlib import Path
r=Path('integrations/conversation-assist/android/debug')
(r/'SystemSpeechProbe.java').write_text('''package com.mcnex.conversation;
import android.app.Instrumentation;import android.os.*;import android.speech.*;import android.content.*;import java.util.concurrent.*;
public class SystemSpeechProbe extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){try{runOnMainSync(()->{Bundle out=new Bundle();boolean available=SpeechRecognizer.isOnDeviceRecognitionAvailable(getTargetContext());out.putBoolean("onDevice",available);if(!available){finish(-1,out);return;}SpeechRecognizer recognizer=SpeechRecognizer.createOnDeviceSpeechRecognizer(getTargetContext());Intent intent=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"ko-KR").putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,true).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);recognizer.checkRecognitionSupport(intent,Executors.newSingleThreadExecutor(),new RecognitionSupportCallback(){public void onSupportResult(RecognitionSupport s){out.putString("installed",s.getInstalledOnDeviceLanguages().toString());out.putString("supported",s.getSupportedOnDeviceLanguages().toString());out.putString("pending",s.getPendingOnDeviceLanguages().toString());new Handler(Looper.getMainLooper()).post(()->{recognizer.destroy();finish(-1,out);});}public void onError(int error){out.putInt("error",error);new Handler(Looper.getMainLooper()).post(()->{recognizer.destroy();finish(0,out);});}});new Handler(Looper.getMainLooper()).postDelayed(()->{out.putString("timeout","true");finish(0,out);},15000);});}catch(Exception e){Bundle b=new Bundle();b.putString("error",e.toString());finish(0,b);}}
}''',encoding='utf-8')
p=r/'AndroidManifest.xml';s=p.read_text(encoding='utf-8').replace('</manifest>','<instrumentation android:name="com.mcnex.conversation.SystemSpeechProbe" android:targetPackage="com.mcnex.conversation"/></manifest>');p.write_text(s,encoding='utf-8')
p=Path('integrations/conversation-assist/android/AndroidManifest.xml');s=p.read_text(encoding='utf-8').replace('<application ','<queries><intent><action android:name="android.speech.RecognitionService"/></intent></queries>\n <application ',1);p.write_text(s,encoding='utf-8')
